import socket
for host in ['api.openai.com', 'example.com']:
    try:
        socket.getaddrinfo(host, 443)
    except OSError as error:
        print(f'EGRESS {host}: DNS lookup failed ({type(error).__name__}: {error})', flush=True)
        continue
    try:
        socket.create_connection((host, 443), timeout=5).close()
        print(f'EGRESS {host}: DNS answered and TCP 443 connected', flush=True)
    except OSError as error:
        print(f'EGRESS {host}: DNS answered but TCP 443 failed ({type(error).__name__})', flush=True)
